import{_ as a,o,c as t,a2 as n}from"./chunks/framework.CDU0sSpB.js";const m=JSON.parse('{"title":"2.1 Connect read-only information sources","description":"Show what the system read and where it came from.","frontmatter":{"title":"2.1 Connect read-only information sources","description":"Show what the system read and where it came from.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-2/2-1.md","filePath":"en/delivery/stage-2/2-1.md","lastUpdated":1794015952000}'),r={name:"en/delivery/stage-2/2-1.md"};function i(s,e,l,d,c,u){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="_2-1-connect-read-only-information-sources" tabindex="-1">2.1 Connect read-only information sources <a class="header-anchor" href="#_2-1-connect-read-only-information-sources" aria-label="Permalink to &quot;2.1 Connect read-only information sources&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented:</strong> Local files, knowledge base, and public web sources; domain allowlists; source status, read time, errors, incremental reads, deduplication, disconnect, reconnect, and clear.</li><li><strong>Still open:</strong> Email and calendar show only &quot;not configured&quot;; there are no credentials, reads, or permission checks.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Let Hearth safely read the sources the user uses every day, and show the source, time, and permission clearly. This step is read-only: no sending, editing, or deleting.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Connect one email source, one calendar source, one file source, and one knowledge base first; do not open everything at once.</li><li>Record source, time, account, and permission for every read so the user can trace where information came from.</li><li>Remove duplicates and update only what changed instead of rereading everything.</li><li>When login expires, permission is missing, or a source is unavailable, tell the user clearly instead of failing silently.</li><li>Provide an entry to disconnect a source and clear what was read from it.</li><li>Verify with a real account: the user can see what was read and confirm that nothing was written.</li></ol>',7)])])}const f=a(r,[["render",i]]);export{m as __pageData,f as default};
